    current_set = set(start_set)
    while True:
        if Fraction(1, 1) in current_set:
            return True

        new_elements = set()
        current_list = list(current_set)
        for i in range(len(current_list)):
            for j in range(i + 1, len(current_list)):
                x = current_list[i]
                y = current_list[j]

                am = (x + y) / 2
                if am not in current_set:
                    new_elements.add(am)

                if x + y != 0:
                    hm = (2 * x * y) / (x + y)
                    if hm not in current_set:
                        new_elements.add(hm)

        if not new_elements:
            return False

        current_set.update(new_elements)
        if len(current_set) > max_elements:
            return False

