from collections import deque

def can_reach_one_improved(m, n, max_elements=10000):
    start_set = {Fraction(m, n), Fraction(n, m)}
    current_set = set(start_set)

    # Use a queue to process elements and their pairs
    queue = deque(list(start_set))

    while queue:
        x = queue.popleft()
        # Try pairing x with every element already in the set
        for y in list(current_set):
            # AM
            am = (x + y) / 2
            if am == 1:
                return True
            if am not in current_set:
                if len(current_set) < max_elements:
                    current_set.add(am)
                    queue.append(am)

            # HM
            if x + y != 0:
                hm = (2 * x * y) / (x + y)
                if hm == 1:
                    return True
                if hm not in current_set:
                    if len(current_set) < max_elements:
                        current_set.add(hm)
                        queue.append(hm)
    return False

